1	//! Saga 33 step 007: outer-shell composer. The html! is split
2	//! across `render_shell_chrome` (header + mode bar) and
3	//! `render_shell_footer` (footer + dialog) so each `html!`
4	//! invocation lives in its own file under the 25-LOC budget.
5	
6	use yew::prelude::*;
7	
8	use crate::mode_callbacks;
9	use crate::render::RenderArgs;
10	use crate::render_callbacks::InputCallbacks;
11	use crate::render_main::{MainArgs, render_main};
12	use crate::render_modes::Modes;
13	use crate::render_shell_chrome::render_shell_chrome;
14	use crate::render_shell_footer::render_shell_footer;
15	use crate::tutorial::run_example;
16	
17	pub fn render_shell(a: RenderArgs, inputs: InputCallbacks, modes: Modes) -> Html {
18	    let cb = mode_callbacks::bundle(
19	        a.ui.lesson_idx.clone(),
20	        a.ui.path_state.clone(),
21	        a.ui.tutorial_initial_view.clone(),
22	        a.callbacks.on_demo.clone(),
23	    );
24	    let on_run_example = run_example(a.callbacks.on_submit.clone(), a.ui.input_value.clone());
25	    let main_args = build_main_args(&a, &cb, &inputs, &modes, on_run_example);
26	    let chrome = render_shell_chrome(&a, &inputs, &modes, &cb);
27	    let footer = render_shell_footer(*a.ui.dialog_open, inputs.close_dialog);
28	    html! {
29	        <>
30	            { chrome }
31	            { render_main(main_args) }
32	            { footer }
33	        </>
34	    }
35	}
36	
37	fn build_main_args<'a>(
38	    a: &'a RenderArgs,
39	    cb: &'a mode_callbacks::ModeCallbacks,
40	    inputs: &InputCallbacks,
41	    modes: &Modes,
42	    on_run_example: Callback<String>,
43	) -> MainArgs<'a> {
44	    MainArgs {
45	        tutorial_active: modes.tutorial_active,
46	        paths_active: modes.paths_active,
47	        cur_lesson: modes.cur_lesson,
48	        lesson_idx: a.ui.lesson_idx.clone(),
49	        initial_view: *a.ui.tutorial_initial_view,
50	        cur_path: modes.cur_path,
51	        cb,
52	        history: &a.active.history,
53	        input_value: &a.ui.input_value,
54	        on_input: inputs.on_input.clone(),
55	        on_keydown: inputs.on_keydown.clone(),
56	        on_run_example,
57	        on_run_batch: a.callbacks.on_run_batch.clone(),
58	        completion_candidates: (*a.ui.completion_candidates).clone(),
59	        on_pick_completion: make_pick_completion(
60	            a.ui.input_value.clone(),
61	            a.ui.completion_candidates.clone(),
62	        ),
63	    }
64	}
65	
66	/// Saga 33 step 043: build the click handler that fires when
67	/// the user clicks a tab-completion chip. Inserts the chosen
68	/// completion at the cursor position and clears the popup.
69	/// Cursor lookup happens at the moment of click against the
70	/// current input value (we don't track cursor in app state).
71	fn make_pick_completion(
72	    input_value: UseStateHandle<String>,
73	    completion_candidates: UseStateHandle<Vec<String>>,
74	) -> Callback<String> {
75	    Callback::from(move |chosen: String| {
76	        let cur = input_value.len();
77	        let (out, _) = crate::completion::apply_completion(&input_value, cur, &chosen);
78	        input_value.set(out);
79	        completion_candidates.set(Vec::new());
80	    })
81	}
82

