fn check_components(rel: &Path, original: &str, root: &Path) -> Result<(), LoaderHelperError> {
    let mut depth: i64 = 0;
    for comp in rel.components() {
        match comp {
            Component::Normal(_) => depth += 1,
            Component::CurDir => {}
            Component::ParentDir => {
                depth -= 1;
                if depth < 0 {
                    return Err(sandbox_err(original, root));
