        Expr::IntLit(n, _) if *n >= 0 => Ok(*n as usize),
        _ => Err(err("[H, W] entries must be non-negative integers")),
    };
    crate::loader::eval_load_images(env, dir, parse_dim(dh)?, parse_dim(dw)?)
}

