use yew::prelude::*;

use crate::app_state::OnboardingState;

fn dismiss(h: &UseStateHandle<bool>) {
    crate::onboarding_storage::write_splash_dismissed();
    h.set(false);
}

pub fn on_dismiss(ob: &OnboardingState) -> Callback<()> {
    let h = ob.show_splash.clone();
    Callback::from(move |()| dismiss(&h))
}

pub fn on_start_tour(ob: &OnboardingState) -> Callback<()> {
    let h = ob.show_splash.clone();
    Callback::from(move |()| dismiss(&h))
}

pub fn on_splash_demo(ob: &OnboardingState, on_demo: Callback<usize>) -> Callback<usize> {
    let h = ob.show_splash.clone();
    Callback::from(move |idx: usize| { dismiss(&h); on_demo.emit(idx); })
}

pub fn on_splash_type(ob: &OnboardingState, input: UseStateHandle<String>) -> Callback<String> {
    let h = ob.show_splash.clone();
    Callback::from(move |text: String| { dismiss(&h); input.set(text); })
}

pub fn on_splash_tutorial(ob: &OnboardingState, lesson: UseStateHandle<Option<usize>>) -> Callback<()> {
    let h = ob.show_splash.clone();
    Callback::from(move |()| { dismiss(&h); lesson.set(Some(0)); })
}

pub fn on_splash_paths(ob: &OnboardingState, path: UseStateHandle<Option<(Option<usize>, usize)>>) -> Callback<()> {
    let h = ob.show_splash.clone();
    Callback::from(move |()| { dismiss(&h); path.set(Some((None, 0))); })
}

