use yew::prelude::*;

#[derive(Properties, PartialEq)]
pub struct SplashProps {
    pub on_dismiss: Callback<()>,
    pub on_start_tour: Callback<()>,
    pub on_demo: Callback<usize>,
    pub on_type: Callback<String>,
    pub on_tutorial: Callback<()>,
    pub on_paths: Callback<()>,
}

const BASICS_DEMO_IDX: usize = 7;

#[function_component(SplashOverlay)]
pub fn splash_overlay(props: &SplashProps) -> Html {
    let cards = render_cards(props);
    let actions = render_actions(props);
    html! {
        <div class="splash-backdrop" role="dialog" aria-label="Welcome">
            <div class="splash-panel">
                <h2>
                    <img src="mlpl-badge.webp" alt="" />
                    {"sw-MLPL"}
                </h2>
                <p class="splash-subtitle">
                    {"An array programming language for learning machine learning, from scalars to transformers."}
                </p>
                { cards }
                { actions }
            </div>
        </div>
    }
}

fn render_cards(props: &SplashProps) -> Html {
    let demo_cb = props.on_demo.clone();
    let on_basics = Callback::from(move |_: MouseEvent| demo_cb.emit(BASICS_DEMO_IDX));
    let type_cb = props.on_type.clone();
    let on_try = Callback::from(move |_: MouseEvent| type_cb.emit("1 + 2".into()));
    let tut_cb = props.on_tutorial.clone();
    let on_tutorial = Callback::from(move |_: MouseEvent| tut_cb.emit(()));
    let path_cb = props.on_paths.clone();
    let on_paths = Callback::from(move |_: MouseEvent| path_cb.emit(()));
    html! {
        <div class="splash-cards">
            <div class="splash-card" onclick={on_basics}>
                <strong>{"Run the Basics demo"}</strong>
                {"See arithmetic, arrays, and broadcasting in action."}
            </div>
            <div class="splash-card" onclick={on_try}>
                <strong>{"Try 1 + 2 in the REPL"}</strong>
                {"Type an expression and press Enter."}
            </div>
            <div class="splash-card" onclick={on_tutorial}>
                <strong>{"Open a tutorial lesson"}</strong>
                {"Guided lessons from scalars to attention."}
            </div>
            <div class="splash-card" onclick={on_paths}>
                <strong>{"Explore learning paths"}</strong>
                {"Structured sequences of lessons and demos."}
            </div>
        </div>
    }
}

fn render_actions(props: &SplashProps) -> Html {
    let dismiss = props.on_dismiss.clone();
    let on_dismiss = Callback::from(move |_: MouseEvent| dismiss.emit(()));
    let tour = props.on_start_tour.clone();
    let on_tour = Callback::from(move |_: MouseEvent| tour.emit(()));
    html! {
        <div class="splash-actions">
            <button class="splash-btn splash-btn-primary" onclick={on_tour}>{"Take a guided tour"}</button>
            <button class="splash-btn splash-btn-secondary" onclick={on_dismiss}>{"Dismiss"}</button>
        </div>
    }
}

