/// Allocate onboarding overlay state from localStorage.
#[hook]
pub fn use_onboarding_state() -> OnboardingState {
    let dismissed = crate::onboarding_storage::read_splash_dismissed();
    OnboardingState {
        show_splash: use_state(move || !dismissed),
    }
}

